keys = {"scoring_rules": RULES, "papers": {"N": N, "I": I, "M": M},
        "paper_numbering": {"1": "N", "2": "I", "3": "M"}}
json.dump(keys, open(f"{D}/keys.json", "w"), indent=1, ensure_ascii=False)
for num, letter in (("1", "N"), ("2", "I"), ("3", "M")):
    p = keys["papers"][letter]
    json.dump({"scoring_rules": RULES, "paper_title": p["title"], "errors": p["errors"]},
              open(f"{D}/key_paper{num}.json", "w"), indent=1, ensure_ascii=False)
print("keys written:", [len(keys["papers"][k]["errors"]) for k in "NIM"])
